import logging
import sys

if sys.version_info[:2] <= (3, 9):
    import pkg_resources
    entry_points = pkg_resources.iter_entry_points
else:
    import importlib.metadata
    entry_points = importlib.metadata.entry_points


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CollectorFactoryRegistry(object):
    """
    Mapping between object type name and corresponding factory class.

    Read package resources to find collector factory plugins among installed packages.

    Object type names occur in collector configuration files.
    """

    _instance = None

    def __init__(self, **kwargs):
        super(CollectorFactoryRegistry, self).__init__(**kwargs)
        self._map = {}
        for entry_point in entry_points(group="CollectorFactory"):
            logger.debug(f"entry point name: {entry_point.name!r}")
            self._map[entry_point.name] = entry_point.load()
        logger.debug(f"factory registry: {self._map!r}")

    def __getitem__(self, type_):
        return self._map[type_]

    @classmethod
    def get_instance(cls):
        if cls._instance is None:
            cls._instance = CollectorFactoryRegistry()
        return cls._instance
